async function main(ctx) {
  const input = ctx.input || {};
  const owner = String(input.owner || '').trim();
  const repo = String(input.repo || '').trim();
  const pull_number = Number(input.pull_number);
  if (!owner) throw new Error('owner is required');
  if (!repo) throw new Error('repo is required');
  if (!Number.isFinite(pull_number)) throw new Error('pull_number is required');
  const out = { owner, repo, pull_number };
  if (input.body != null) out.body = String(input.body);
  if (input.event != null && String(input.event).trim() !== '') out.event = String(input.event).trim();
  if (Array.isArray(input.comments) && input.comments.length > 0) out.comments = input.comments;
  return out;
}

async function main(ctx) {
  const resp = ctx.lastOutputOf('post_review') || {};
  const review = (resp.body && typeof resp.body === 'object') ? resp.body : {};
  return {
    success: true,
    reviewId: review.id ?? null,
    state: review.state || null,
    htmlUrl: review.html_url || null
  };
}
